mapper.select:
select t.*
from ${mainTable} t
where t.organization_id = #{orgId}

    and t.${formColumn} = #{formValue}

  and t.${column} >= #{start}
  and t.${column} < #{end}

select t.*,
       cast(f.field_value as signed) as due_time
from ${mainTable} t
inner join ${fieldTable} f on f.resource_id = t.id and f.field_id = #{fieldId}
where t.organization_id = #{orgId}

    and t.${formColumn} = #{formValue}

  and cast(f.field_value as signed) >= #{start}
  and cast(f.field_value as signed) < #{end}
